};

  in vec4 v_color;

  #if USE_TEXTURE
  in vec2 v_uv0;
  uniform sampler2D texture;
  uniform sampler2D normalTex;
  #endif

  uniform PROPERTIES {
    vec4 lightPos;
    vec4 lightColor;
    vec4 bgColor;
    float fluxaySlope;
    float fluxayRun;
    float time;
    float bgTime;
  }

  float lerpF(float a, float b, float w) {
    return a * (1.0 - w) + b * w;
  }

