  vec4 fluxay2(vec4 texColor, vec3 normalRgb) {
    if (texColor[3] == 0.0 || normalRgb.b <= 0.3) {
      return texColor;
    }
    float width = 0.6;
    float start = tan(time/1.414);
    float strength = 1.0;
    float offset = fluxaySlope;

    float right = start - pow(v_uv0.y, 1.5) * offset;
    float left = right - width;
    float midx = max(0.0000001, (left + right) / 2.0);
    if (v_uv0.x < right && v_uv0.x > left) {
      vec3 improve = lightColor.xyz * clamp(width - abs(v_uv0.x - midx)/midx, 0.0, 1.0) * strength * normalRgb.b;
      vec3 result = improve + vec3(texColor.r, texColor.g, texColor.b);
      return vec4(result, texColor.a);
    } else {
      return texColor;
    }
  }

  vec4 fluxay3(vec4 texColor, vec3 normalRgb) {
    if (texColor[3] == 0.0 || normalRgb.b <= 0.3) {
      return texColor;
    }
    float x = v_uv0.x * normalRgb.r;
    float y = v_uv0.y * normalRgb.g;
    float width = 0.2;
    float start = tan(time/1.414);
    float strength = 0.2;
    float offset = fluxaySlope;
    float right = start - pow(y, 1.0) * offset;
    float left = right - width;
    float midx = (right + left) / 2.0;
    if (x < right && x > left) {
      vec3 improve = lightColor.xyz * clamp((width - 2.0 * abs(x - midx))/width, 0.0, 1.0) * strength;
      vec4 col = vec4(improve + vec3(texColor.r, texColor.g, texColor.b), lightColor.a);

      return col;
    } else {
      return texColor;
    }
  }

  vec4 fluxay4(vec4 texColor, vec3 normalRgb) {
    if (texColor[3] == 0.0 || normalRgb.b <= 0.0) {
      return texColor;
    }
    float width = 0.6;
    float start = tan(time/1.414) * (1.0 + width);
    float strength = .7;
    float offset = fluxaySlope;
    float left = start - v_uv0.y * offset - width;
    float right = left + width;
    float midx = max(0.0000001, (left + right) / 2.0);
    if (v_uv0.x < right && v_uv0.x > left) {
      vec3 improve = lightColor.xyz * clamp((width - 2.0 * abs(v_uv0.x - midx))/width, 0.0, 1.0) * strength * normalRgb.b;
      vec3 result = improve + vec3(texColor.r, texColor.g, texColor.b);
      return vec4(result, texColor.a);
    } else {
      return texColor;
    }
  }

  vec4 lambertian(vec4 texColor, vec3 normalRgb) {
    if (texColor[3] == 0.0) {
      return texColor;
    }
    vec4 LightColor = lightColor;
    vec4 AmbientColor = vec4(1.0, 1.0, 1.0, 0.9);
    vec3 Falloff = vec3(0.01, .01, 0.1);
    vec4 DiffuseColor = texColor;
    vec3 NormalMap = normalRgb;
    vec3 LightDir = lightPos.xyz;
    float D = length(LightDir);
    vec3 N = normalize(NormalMap * 2.0 - 1.0);
    vec3 L = normalize(LightDir);
    float dotRet = dot(N, L);
    vec3 Diffuse = (LightColor.rgb * LightColor.a) * max(dotRet, 0.0);
    vec3 Ambient = AmbientColor.rgb * AmbientColor.a;
    float AttenuationFactor = 1.1;
    float Attenuation = AttenuationFactor / ( Falloff.x + (Falloff.y*D) + (Falloff.z*D*D) );
    vec3 Intensity = Ambient + Diffuse * Attenuation;
    return vec4(DiffuseColor.rgb * Intensity, texColor.a);
  }

  float rand(vec2 coord) {
    return fract(sin(dot(coord, vec2(56.0, 78.0)) * 100.0) * 100.0);
  }

  float noise(vec2 coord) {
    vec2 adjCoord = mod(coord, 20.0);
    vec2 i = floor(adjCoord);
    vec2 f = fract(adjCoord);

    float a = rand(i);
    float b = rand(i + vec2(1.0, 0.0));
    float c = rand(i + vec2(0.0, 1.0));
    float d = rand(i + vec2(1.0, 1.0));

    vec2 cubic = smoothstep(0.0, 1.0, f);

    float value = mix(a, b, cubic.x) + (c - a) * cubic.y * (1.0 - cubic.x) + (d - b) * cubic.x * cubic.y;
    return value;
  }

  float fbm(vec2 coord) {
    float value = 0.0;
    float scale = 0.5;
    for (int i = 0; i < 2; ++ i) {
      value += noise(coord) * scale;
      coord *= 2.0;
      scale *= 0.5;
    }
    return fract(value);
  }

  vec4 alphaHandle(vec4 texColor) {
    float t = bgTime;
    if (texColor[3] == 1.0 || t == 0.0) return texColor;
    vec2 coord = v_uv0 * 20.0;
    vec2 motion = vec2(fbm(coord + vec2(t * 2.0, t * 2.0))) + vec2(t * 2.0, t * 2.0);
    vec4 final = vec4(bgColor.r, bgColor.g, bgColor.b, fbm(coord + motion) * bgColor.a);
    float pct = smoothstep(0.0, final.a, texColor.a);
    return mix(final, texColor, pct);
  }
  void main () {
    vec4 texColor = texture2D(texture, v_uv0);
    vec3 normalRgb = texture2D(normalTex, v_uv0).rgb;
    vec4 color1 = lambertian(texColor, normalRgb);
    vec4 color2 = fluxayRun * v_color * fluxay4(color1, normalRgb) + (1.0 - fluxayRun) * v_color * color1;
    vec4 o = alphaHandle(color2);
    #if CC_USE_ALPHA_ATLAS_TEXTURE
      o.a *= texture2D(texture, v_uv0 + vec2(0, 0.5)).r;
    #endif
    gl_FragColor = o;
  }

